64	async function callModel(prompt: string, model: string): Promise<LlmResult> {
65	  const apiKey = Deno.env.get('OPENROUTER_API_KEY');
66	  if (!apiKey) throw new Error('OPENROUTER_API_KEY not set');
67	  const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
68	    method: 'POST',
69	    headers: {
70	      'Authorization': `Bearer ${apiKey}`,
71	      'Content-Type': 'application/json',
72	      'HTTP-Referer': 'https://momma-stock-insight.vercel.app',
73	      'X-Title': 'momma-match-review',
74	    },
75	    body: JSON.stringify({
76	      model,
77	      messages: [
78	        { role: 'system', content: SYSTEM_PROMPT },
79	        { role: 'user', content: prompt },
80	      ],
81	      temperature: 0,
82	      // Força JSON limpo (sem fences/preâmbulo) — melhora confiabilidade do modelo
83	      // primário (grok) e dos demais; o parse de fallback ainda cobre quem ignorar.
84	      response_format: { type: 'json_object' },
85	    }),
86	  });
87	  if (!res.ok) {
88	    const txt = await res.text().catch(() => '');
89	    throw new Error(`OpenRouter ${model}: ${res.status} ${txt}`);
90	  }
91	  const data = await res.json();
92	  return { content: data?.choices?.[0]?.message?.content ?? '', usage: data?.usage ?? null };
93	}
